script:
const phanHe = ctx.val('phan_he', 'maintenance').trim().toLowerCase() || 'maintenance';

await step('Điều hướng vào Thiết Lập -> Thiết lập SLA', async () => {
  if (!page.url().includes(`/${phanHe}/`)) {
    await page.goto(`https://tasks.zuizui.io/${phanHe}/dashboard`, { waitUntil: 'domcontentloaded' });
  }
  await page.waitForLoadState('networkidle', { timeout: 25000 }).catch(() => {});
  const setupBtn = page.getByRole('button', { name: 'Thiết Lập' });
  if (await setupBtn.isVisible().catch(() => false)) await setupBtn.click();
  const link = page.getByRole('link', { name: 'Thiết lập SLA' });
  await link.waitFor({ timeout: 10000 });
  await link.click();
  await page.waitForLoadState('networkidle', { timeout: 25000 }).catch(() => {});
});

await step('Kiểm tra nội dung trang Thiết lập SLA', async () => {
  const txt = await page.locator('body').innerText();
  assert(txt.length > 50, 'Trang Thiết lập SLA không có nội dung');
  assert(/SLA/i.test(txt), 'Không tìm thấy nội dung SLA trên trang');
  ctx.log('Đã tải thành công trang Thiết lập SLA tại: ' + page.url());
});
